\pagestyle{empty}

\begin{tikzpicture}[scale=1.0, every node/.style={transform shape}]

\node[decision](decision1) {\parbox{2cm} {\small\center  Does ${\textrm{gcd}(a,n)=1?}$ \\[5pt]}};    
\node[block, below left of=decision1, xshift=-7em, fill=blue!10!white] (divergent) {A unique solution};
\node[decision, below right of=decision1, xshift=9em, yshift=-5em](decision2)
	{\parbox{2cm}{\small\center Does ${\textrm{gcd}(a,n)\: | \: b?}$}};   
\node [block, below left of=decision2, xshift=-5em, fill=blue!10!white, inner sep=5pt] (many_solutions)  
	{{\textrm{gcd}(a,n) solutions}};
\node [block, below right of=decision2, xshift=5em, fill=blue!10!white, inner sep=5pt] (no_solutions) 
	{{No solutions }};

%Arrows

\path [line] (decision1) -| node[yshift=0.5em, xshift=3em] {\bf yes} (divergent);
\path [line] (decision1) -| node[yshift=0.5em, xshift=-3em] {\bf no} (decision2);

\path [line] (decision2) -| node[yshift=0.5em, xshift=3em] {\bf yes} (many_solutions);
\path [line] (decision2) -| node[yshift=0.5em, xshift=-3em] {\bf no} (no_solutions);  

\end{tikzpicture}
\end{document}

